import sys
def fonk1(a1, b3):
    return (a1 - 1) * (b3 - 1)
def fonk2(a, b6):
    b4, b1 = 1, 0
    b5, b2 = 0, 1
    while b6:
        b3 = a
        b1, b4 = b4 - b3 * b1, b1
        b2, b5 = b5 - b3 * b2, b2
        a, b6 = b6, a % b6
    return a, b4, b5
def fonk3(a, b6):
    return fonk2(a, b6)[0] == 1
def fonk4(b7, b8):
    for i in range(3, b8, 2):
        if fonk3(i, b7) and fonk3(i, b8):
            return i
def fonk5(a, m):
    g, b1, b2 = fonk2(a, m)
    if g != 1:
        raise Exception('No modular inverse')
    return b1 % m
